/** Slug -> component, for every mark the registry vendors. */
export const BRAND_ICONS: Record<BrandIconName, BrandIcon> = {
  "airtable": BrandAirtableIcon,
  "box": BrandBoxIcon,
  "cloudflare": BrandCloudflareIcon,
  "dropbox": BrandDropboxIcon,
  "figma": BrandFigmaIcon,
  "github": BrandGithubIcon,
  "gitlab": BrandGitlabIcon,
  "jira": BrandJiraIcon,
  "linear": BrandLinearIcon,
  "netlify": BrandNetlifyIcon,
  "notion": BrandNotionIcon,
  "paypal": BrandPaypalIcon,
  "posthog": BrandPosthogIcon,
  "sentry": BrandSentryIcon,
  "slack": BrandSlackIcon,
  "stripe": BrandStripeIcon,
  "supabase": BrandSupabaseIcon,
  "todoist": BrandTodoistIcon,
}

/** The component for a brand slug (compile-time checked). */
export function brandIcon(name: BrandIconName): BrandIcon {
  return BRAND_ICONS[name]
}
